window.HOEREN_TESTS[43] = {"id":"musik-und-konzerte","name":"Musik und Konzerte","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Konzert-Besucher: Das Rock-Konzert mit der Band Silbermond ist verschoben! Wegen Krankheit der Sängerin neuer Termin: Samstag, 15. März, 20 Uhr, gleicher Ort. Es ist nicht abgesagt, es findet nur später statt, also fast wie geplant. Tickets bleiben gültig. Wer nicht kommen kann, bekommt sein Geld zurück. Wir entschuldigen uns für die Umstände.","gender":"m","q":"Was ist passiert?","opts":["Konzert abgesagt.","Konzert findet wie geplant statt.","Konzert verschoben."],"correct":2},{"transcript":"Hallo Tom, hier ist Lisa. Ich habe zwei Karten für das Jazz-Konzert am Freitag — meine Schwester kann nicht. Möchtest du mit? Eintritt ist gratis für dich, ich lade dich ein. Verkaufen will ich die Karten nicht, und verschenken auch nicht an Fremde, ich lade dich ein. Ruf bitte zurück bis morgen. Sonst frage ich Anna. Würde mich freuen!","gender":"f","q":"Was möchte Lisa?","opts":["Tom einladen.","Karten verkaufen.","Karten verschenken."],"correct":0},{"transcript":"Achtung Musik-Schüler: Der Klavier-Unterricht morgen fällt aus. Lehrer Schmidt ist krank. Neuer Termin: nächsten Mittwoch um 16 Uhr, gleicher Raum. Wer einen anderen Lehrer sucht, soll bitte bei der Schule anrufen für einen anderen Termin. Hausaufgaben bitte trotzdem machen für nächstes Mal. Bei Fragen rufen Sie bitte im Sekretariat an.","gender":"f","q":"Was sollen Schüler tun?","opts":["Zu Lehrer Schmidt gehen.","Hausaufgaben machen.","Anderen Lehrer suchen."],"correct":1},{"transcript":"Hi Markus, ich habe ein neues Instrument gekauft! Schon immer wollte ich Gitarre spielen, jetzt ist es so weit. Kein Klavier und keine Geige, eine Gitarre musste es sein. Habe einen guten Lehrer gefunden — Privat-Unterricht, einmal die Woche. Sehr nett. Du musst kommen und zuhören. Ehrlich, du wirst lachen, ich bin noch schlecht!","gender":"m","q":"Was hat der Sprecher gekauft?","opts":["Eine Gitarre.","Ein Klavier.","Eine Geige."],"correct":0},{"transcript":"Liebe Hörer, in der Mediathek finden Sie ab heute neue klassische Musik kostenlos: Beethoven Symphonien, Mozart Konzerte, Bach Klavierwerke. Auch moderne Komponisten wie Glass sind dabei. Login mit Ihrer Bibliotheks-Karte. Nicht unbegrenzt und keine zehn Alben, genau fünf Alben pro Monat. Viel Spaß beim Hören!","gender":"f","q":"Wie viele Alben pro Monat sind kostenlos?","opts":["Unbegrenzt.","Zehn Alben.","Fünf Alben."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer mag welche Musik? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Das große Konzert am Samstag braucht noch eine klare Reihenfolge."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Jeder mag etwas anderes. Wir können nicht alles an einem Abend spielen."},{"speaker":"Lukas","gender":"m","text":"Bei mir läuft Rock. Die Gitarre muss richtig laut sein."},{"speaker":"Lisa","gender":"f","text":"Dann eröffnest du den langen Abend. Das passt gut zu deiner Gruppe."},{"speaker":"Lukas","gender":"m","text":"Legt noch jemand Country auf?"},{"speaker":"Lisa","gender":"f","text":"Nein. Country mag hier keiner."},{"speaker":"Lukas","gender":"m","text":"Du hörst abends oft Geige und auch Klavier."},{"speaker":"Lisa","gender":"f","text":"Ich bleibe bei der Klassik. Ein ruhiges Stück kommt direkt nach der Pause."},{"speaker":"Lukas","gender":"m","text":"Tom bringt ein goldenes Blasinstrument mit."},{"speaker":"Lisa","gender":"f","text":"Tom spielt Jazz. Zwei Stücke mit dem Saxofon reichen ihm."},{"speaker":"Lukas","gender":"m","text":"Sara bewegt sich schnell zur Musik und spricht im Takt."},{"speaker":"Lisa","gender":"f","text":"Sara kommt mit Hip-Hop. Sie tritt als Dritte auf die Bühne."},{"speaker":"Lukas","gender":"m","text":"Spielen wir danach auch Reggae?"},{"speaker":"Lisa","gender":"f","text":"Nein. Reggae hören wir auch nicht."},{"speaker":"Lukas","gender":"m","text":"Tim mischt am Computer lange neue Töne."},{"speaker":"Lisa","gender":"f","text":"Tim spielt Elektro. Die großen Boxen müssen das aushalten."},{"speaker":"Lukas","gender":"m","text":"Dann ist die Reihenfolge für den ganzen Abend fest."},{"speaker":"Lisa","gender":"f","text":"Ich schreibe sie an die Tür vom Proberaum."}],"options":[{"letter":"a","text":"Jazz"},{"letter":"b","text":"Klassik"},{"letter":"c","text":"Country"},{"letter":"d","text":"Reggae"},{"letter":"e","text":"Hip-Hop"},{"letter":"f","text":"Rock"},{"letter":"g","text":"Pop"},{"letter":"h","text":"Volksmusik"},{"letter":"i","text":"Elektro"}],"items":[{"person":"Lukas","correct":"f"},{"person":"Lisa","correct":"b"},{"person":"Tom","correct":"a"},{"person":"Sara","correct":"e"},{"person":"Tim","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Ich suche zwei Karten für Beethoven am Samstag."},{"speaker":"Verkäufer","gender":"m","text":"Vorne ist leider alles ausverkauft. Mittlere Plätze gibt es auch keine mehr."},{"speaker":"Kundin","gender":"f","text":"Schade! Was haben Sie denn noch?"},{"speaker":"Verkäufer","gender":"m","text":"Nur noch hintere Plätze für 25 Euro pro Karte."},{"speaker":"Kundin","gender":"f","text":"Gut, dann nehme ich zwei hintere Plätze. Danke für Samstag!"}],"q":"Welche Plätze nimmt sie?","opts":["Hintere Plätze.","Mittlere Plätze.","Vordere Plätze."],"correct":0},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, ich möchte ein Instrument lernen!"},{"speaker":"Mutter","gender":"f","text":"Schön! Welches denn? Gitarre oder Schlagzeug?"},{"speaker":"Sohn","gender":"m","text":"Schlagzeug! Das ist laut und cool!"},{"speaker":"Mutter","gender":"f","text":"Zu laut für die Wohnung! Wie wäre es mit Klavier?"},{"speaker":"Sohn","gender":"m","text":"Na gut, dann lerne ich Klavier. Ab wann?"},{"speaker":"Mutter","gender":"f","text":"Ab Montag, ich melde dich heute noch an. Du wirst sehen, es macht Spaß!"}],"q":"Welches Instrument lernt der Sohn?","opts":["Gitarre.","Schlagzeug.","Klavier."],"correct":2},{"lines":[{"speaker":"Junge","gender":"m","text":"Papa, wann ist das Konzert heute Abend?"},{"speaker":"Vater","gender":"m","text":"Um 19 Uhr. Freust du dich schon?"},{"speaker":"Junge","gender":"m","text":"Ja! Wo ist es, im Stadion oder in der Halle?"},{"speaker":"Vater","gender":"m","text":"Weder noch, es ist Open Air im Stadtpark."},{"speaker":"Junge","gender":"m","text":"Cool, im Park! Darf ich Freunde mitbringen?"},{"speaker":"Vater","gender":"m","text":"Klar, frag sie schnell. Wir gehen um halb sieben los."}],"q":"Wo ist das Konzert?","opts":["Im Stadion.","In der Halle.","Im Park."],"correct":2},{"lines":[{"speaker":"Anna","gender":"f","text":"Markus, hörst du morgens gerne Radio in der Küche?"},{"speaker":"Markus","gender":"m","text":"Nein, Radio mag ich nicht. Ich höre lieber Streaming, Spotify."},{"speaker":"Anna","gender":"f","text":"Kostenlos oder bezahlt? Da gibt es doch Werbung."},{"speaker":"Markus","gender":"m","text":"Premium, für 10 Euro im Monat. Ganz ohne Werbung."},{"speaker":"Anna","gender":"f","text":"Verstehe! Und CDs hast du gar keine mehr?"},{"speaker":"Markus","gender":"m","text":"Doch, ein paar alte CDs im Regal, aber ich höre sie nie."}],"q":"Wie hört Markus Musik?","opts":["Spotify Premium.","Radio.","CDs."],"correct":0},{"lines":[{"speaker":"Verkäuferin","gender":"f","text":"Guten Tag! Suchen Sie eine Schallplatte oder eine CD?"},{"speaker":"Kunde","gender":"m","text":"Eine Schallplatte, bitte. Ich habe einen Plattenspieler von meinem Opa."},{"speaker":"Verkäuferin","gender":"f","text":"Schön! Welcher Künstler soll es sein? Auch ein Buch über Musik?"},{"speaker":"Kunde","gender":"m","text":"Nein, kein Buch, nur die Platte. Haben Sie Beatles?"},{"speaker":"Verkäuferin","gender":"f","text":"Ja, hier bitte. Das macht 20 Euro."}],"q":"Was kauft der Kunde?","opts":["Eine CD.","Eine Schallplatte.","Ein Buch."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Klinger, einer Geigerin im Orchester. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Klinger, Sie spielen seit 25 Jahren in der Berliner Philharmonie. Wie sind Sie zu dieser Karriere gekommen?"},{"speaker":"Klinger","gender":"f","text":"Meine Eltern waren beide Musiker, das war zu Hause normal. Mit 5 Jahren habe ich angefangen Geige zu lernen. Mit 18 Musikhochschule, mit 25 erste Stelle in einem kleineren Orchester, mit 30 Berlin. Glück hatte ich auch — Talent allein reicht nicht."},{"speaker":"Reporter","gender":"m","text":"Wie viel üben Sie?"},{"speaker":"Klinger","gender":"f","text":"Täglich 4 bis 5 Stunden, auch noch heute. Ohne Üben verliert man schnell. Sonntags mache ich Pause, sonst täglich. Manchmal langweilig, aber nötig. Das gehört zum Beruf."},{"speaker":"Reporter","gender":"m","text":"Welche Musik spielen Sie am liebsten?"},{"speaker":"Klinger","gender":"f","text":"Mozart am meisten — leichter, hellster Klang, ich finde ihn perfekt. Beethoven mag ich auch, schwerer aber kraftvoll. Moderne Musik weniger — manchmal zu schräg für meinen Geschmack. Aber als Profi muss ich alles spielen."},{"speaker":"Reporter","gender":"m","text":"Wie ist das Leben in einem Orchester?"},{"speaker":"Klinger","gender":"f","text":"Viel Stress! Probe morgens, Konzert abends, oft Tourneen. Wenig Privatleben. Aber wenn das Konzert gut läuft und das Publikum applaudiert — alles wird belohnt."},{"speaker":"Reporter","gender":"m","text":"Hören Sie privat auch Musik?"},{"speaker":"Klinger","gender":"f","text":"Wenig klassische Musik — beruflich genug. Privat eher Jazz oder Pop, etwas anderes. Mein Mann ist auch Musiker, wir hören manchmal zusammen."}],"items":[{"q":"Frau Klingers Eltern waren auch Musiker.","correct":"ja"},{"q":"Sie übt jeden Tag der Woche.","correct":"nein"},{"q":"Sie mag moderne Musik am liebsten.","correct":"nein"},{"q":"Das Leben im Orchester ist stressig.","correct":"ja"},{"q":"Privat hört sie hauptsächlich klassische Musik.","correct":"nein"}]}]};
